#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;

    string s = "codeforces";
    vector<long long> cnt(10, 1);
    long long product = 1;
    int i = 0;

    while (product < n) {
        product /= cnt[i];
        ++cnt[i];
        product *= cnt[i];
        i = (i + 1) % 10;
    }

    for (int j = 0; j < 10; ++j) {
        cout << string(cnt[j], s[j]);
    }

    return 0;
}

